The vulnerability is in `generic_unpack` in unpack.c. The issue is a heap-buffer-overflow reading 4 bytes past a heap-allocated buffer.

Let me understand the flow:
1. `readCoreScanlinePart` reads scanline chunks
2. For each chunk, it computes `bytes` = sum over channels of `width * user_bytes_per_element * lines_per_chunk`
3. It allocates `imgdata` of size `bytes`
4. It sets `outc.decode_to_ptr = dptr`, `outc.user_pixel_stride = outc.user_bytes_per_element`, `outc.user_line_stride = outc.user_pixel_stride * width`
5. Then `exr_decoding_run` is called

In `exr_decoding_run`:
- `read_fn` reads the chunk data into `packed_buffer`
- `update_pack_unpack_ptrs` allocates `unpacked_buffer` of size `decode->chunk.unpacked_size`
- `decompress_fn` decompresses packed -> unpacked
- `unpack_and_convert_fn` (which is `generic_unpack`) reads from `unpacked_buffer` (srcbuffer) and writes to `decode_to_ptr` (cdata)

In `generic_unpack`:
```c
const uint8_t* srcbuffer = decode->unpacked_buffer;
...
for (int y = 0; y < decode->chunk.height; ++y)
{
    int cury = y + decode->chunk.start_y;
    for (int c = 0; c < decode->channel_count; ++c)
    {
        exr_coding_channel_info_t* decc = (decode->channels + c);
        cdata = decc->decode_to_ptr;
        w     = decc->width;
        bpc   = decc->bytes_per_element;
        ubpc  = decc->user_pixel_stride;
        if (decc->y_samples > 1)
        {
            if ((cury % decc->y_samples) != 0) continue;
            ...
        }
        ...
        UNPACK_SAMPLES (w)   // reads w samples from srcbuffer
        srcbuffer += w * bpc;
    }
}
```

So `generic_unpack` reads `w * bpc` bytes per channel per line from `srcbuffer` (the unpacked_buffer). The total bytes read = sum over y, c of `w_c * bpc_c`.

The unpacked_buffer is allocated with size `decode->chunk.unpacked_size`, which is computed by `compute_chunk_unpack_size`.

Now, the key question: when can the bytes read by `generic_unpack` exceed `unpacked_size`?

Let me look at `compute_chunk_unpack_size`:
```c
static uint64_t
compute_chunk_unpack_size (
    int y, int width, int height, int lpc, const struct _internal_exr_part* part)
{
    uint64_t unpacksize = 0;
    if (part->chan_has_line_sampling || height != lpc)
    {
        const exr_attr_chlist_t* chanlist = part->channels->chlist;
        for (int c = 0; c < chanlist->num_channels; ++c)
        {
            const exr_attr_chlist_entry_t* curc = (chanlist->entries + c);
            uint64_t chansz = ((curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4);
            chansz *= ((uint64_t) width);
            if (curc->x_sampling > 1) chansz /= ((uint64_t) curc->x_sampling);
            chansz *= ((uint64_t) height);
            if (curc->y_sampling > 1)
            {
                if (height > 1)
                {
                    if (curc->y_sampling > height)
                        chansz /= ((uint64_t) height);
                    else
                        chansz /= ((uint64_t) curc->y_sampling);
                }
                else if ((y % ((int) curc->y_sampling)) != 0)
                    chansz = 0;
            }
            unpacksize += chansz;
        }
    }
    else
        unpacksize = part->unpacked_size_per_chunk;
    return unpacksize;
}
```

